1	package monitor
2	
3	import (
4		"fmt"
5		"os"
6		"path/filepath"
7		"strconv"
8		"strings"
9	)
10	
11	// GPUInfo describes a discoverable AMD GPU.
12	type GPUInfo struct {
13		Index   int    // card index from sysfs (e.g., 1 for card1)
14		Name    string // product name or "GPU <index>"
15		SysPath string // e.g., "/sys/class/drm/card1/device"
16		hwmon   string // cached hwmon dir path; resolved lazily
17	}
18	
19	// GPUMetrics is a point-in-time hardware telemetry snapshot.
20	type GPUMetrics struct {
21		Index     int
22		Name      string
23		BusyPct   int     // 0–100, from gpu_busy_percent
24		VRAMTotal uint64  // bytes, from mem_info_vram_total
25		VRAMUsed  uint64  // bytes, from mem_info_vram_used
26		TempC     float64 // °C, from temp1_input / 1000
27		PowerW    float64 // W, from power1_average / 1_000_000
28	}
29	
30	// DiscoverGPUs finds all AMD GPUs exposed via the standard sysfs DRM tree.
31	// Returns an empty slice when no GPU sysfs files are present (e.g. non-AMD
32	// system, container without device access).
33	func DiscoverGPUs() []GPUInfo {
34		return discoverGPUs("/sys/class/drm")
35	}
36	
37	func discoverGPUs(base string) []GPUInfo {
38		pattern := filepath.Join(base, "card*/device/gpu_busy_percent")
39		matches, err := filepath.Glob(pattern)
40		if err != nil || len(matches) == 0 {
41			return nil
42		}
43	
44		gpus := make([]GPUInfo, 0, len(matches))
45		for _, match := range matches {
46			// match  = <base>/card<N>/device/gpu_busy_percent
47			deviceDir := filepath.Dir(match)   // <base>/card<N>/device
48			cardDir := filepath.Dir(deviceDir) // <base>/card<N>
49			cardName := filepath.Base(cardDir) // "card<N>"
50	
51			var index int
52			fmt.Sscanf(cardName, "card%d", &index) //nolint:errcheck
53	
54			gpus = append(gpus, GPUInfo{
55				Index:   index,
56				Name:    gpuName(deviceDir, index),
57				SysPath: deviceDir,
58			})
59		}
60		return gpus
61	}
62	
63	// gpuName tries to derive a human-readable GPU identifier from the uevent file.
64	func gpuName(deviceDir string, index int) string {
65		data, err := os.ReadFile(filepath.Join(deviceDir, "uevent"))
66		if err != nil {
67			return fmt.Sprintf("GPU %d", index)
68		}
69		for _, line := range strings.Split(string(data), "\n") {
70			if v, ok := strings.CutPrefix(line, "PCI_SLOT_NAME="); ok {
71				return v
72			}
73		}
74		return fmt.Sprintf("GPU %d", index)
75	}
76	
77	// ReadGPUMetrics reads current metrics for each GPU in gpus.
78	// If a sysfs file cannot be read, the corresponding field is zero.
79	func ReadGPUMetrics(gpus []GPUInfo) []GPUMetrics {
80		out := make([]GPUMetrics, 0, len(gpus))
81		for i := range gpus {
82			out = append(out, gpus[i].read())
83		}
84		return out
85	}
86	
87	func (g *GPUInfo) read() GPUMetrics {
88		m := GPUMetrics{Index: g.Index, Name: g.Name}
89		m.BusyPct = readSysInt(filepath.Join(g.SysPath, "gpu_busy_percent"))
90		m.VRAMTotal = readSysUint64(filepath.Join(g.SysPath, "mem_info_vram_total"))
91		m.VRAMUsed = readSysUint64(filepath.Join(g.SysPath, "mem_info_vram_used"))
92	
93		if hwmon := g.resolveHwmon(); hwmon != "" {
94			m.TempC = float64(readSysInt64(filepath.Join(hwmon, "temp1_input"))) / 1000.0
95			m.PowerW = float64(readSysInt64(filepath.Join(hwmon, "power1_average"))) / 1_000_000.0
96		}
97		return m
98	}
99	
100	// resolveHwmon returns the hwmon subdirectory path, re-globbing if the cached
101	// path is stale (hwmon index can change across driver reloads).
102	func (g *GPUInfo) resolveHwmon() string {
103		if g.hwmon != "" {
104			if _, err := os.Stat(g.hwmon); err == nil {
105				return g.hwmon
106			}
107			g.hwmon = "" // stale; re-resolve below
108		}
109		matches, err := filepath.Glob(filepath.Join(g.SysPath, "hwmon/hwmon*"))
110		if err != nil || len(matches) == 0 {
111			return ""
112		}
113		g.hwmon = matches[0]
114		return g.hwmon
115	}
116	
117	func readSysInt(path string) int {
118		data, err := os.ReadFile(path)
119		if err != nil {
120			return 0
121		}
122		v, _ := strconv.Atoi(strings.TrimSpace(string(data)))
123		return v
124	}
125	
126	func readSysUint64(path string) uint64 {
127		data, err := os.ReadFile(path)
128		if err != nil {
129			return 0
130		}
131		v, _ := strconv.ParseUint(strings.TrimSpace(string(data)), 10, 64)
132		return v
133	}
134	
135	func readSysInt64(path string) int64 {
136		data, err := os.ReadFile(path)
137		if err != nil {
138			return 0
139		}
140		v, _ := strconv.ParseInt(strings.TrimSpace(string(data)), 10, 64)
141		return v
142	}
143	
