10	func writeConfig(t *testing.T, content string) string {
11		t.Helper()
12		dir := t.TempDir()
13		path := filepath.Join(dir, "config.yaml")
14		if err := os.WriteFile(path, []byte(content), 0o600); err != nil {
15			t.Fatal(err)
16		}
17		return path
18	}
