25	func TestLoad_ValidMixed(t *testing.T) {
26		path := writeConfig(t, `
27	listen: ":9090"
28	backends:
29	  local:
30	    model: "Qwen/Qwen3-Coder-30B-A3B-Instruct-GGUF:Q4_K_M"
31	    context: 4096
32	    gpu_layers: 35
33	  openai:
34	    url: "https://api.openai.com/v1"
35	    api_key: "sk-test"
36	    provider: "openai"
37	peers:
38	  - "10.0.0.2:8080"
39	`)
40		setEnv(t, "WIRE_CONFIG", path)
41	
42		cfg, err := Load()
43		if err != nil {
44			t.Fatalf("unexpected error: %v", err)
45		}
46	
47		if cfg.Listen != ":9090" {
48			t.Errorf("listen: got %q, want %q", cfg.Listen, ":9090")
49		}
50		if len(cfg.Backends) != 2 {
51			t.Errorf("backends: got %d, want 2", len(cfg.Backends))
52		}
53	
54		local := cfg.Backends["local"]
55		if !local.IsManaged() {
56			t.Error("local backend should be managed")
57		}
58		if local.IsExternal() {
59			t.Error("local backend should not be external")
60		}
61		if local.Model != "Qwen/Qwen3-Coder-30B-A3B-Instruct-GGUF:Q4_K_M" {
62			t.Errorf("local.model: got %q", local.Model)
63		}
64	
65		ext := cfg.Backends["openai"]
66		if !ext.IsExternal() {
67			t.Error("openai backend should be external")
68		}
69		if ext.Provider != "openai" {
70			t.Errorf("openai.provider: got %q, want %q", ext.Provider, "openai")
71		}
72	
73		if len(cfg.Peers) != 1 || cfg.Peers[0] != "10.0.0.2:8080" {
74			t.Errorf("peers: got %v", cfg.Peers)
75		}
76	}
