1	package cli
2	
3	import (
4		"context"
5		"encoding/json"
6		"fmt"
7		"log/slog"
8		"net/http"
9		"os"
10		"os/signal"
11		"strings"
12		"sync"
13		"syscall"
14		"time"
15	
16		"flag"
17	
18		"github.com/nogo/wire/internal"
19		"github.com/nogo/wire/internal/build"
20		"github.com/nogo/wire/internal/config"
21		"github.com/nogo/wire/internal/gateway"
22		"github.com/nogo/wire/internal/pidfile"
23		"github.com/nogo/wire/internal/process"
24	)
25	
26	const usageText = `Usage: wire <command> [arguments]
27	
28	Commands:
29	  start               Start the gateway (foreground)
30	  stop                Stop the running gateway
31	  status              Show backend status
32	  swap <backend> <model>  Hot-swap a backend's model
33	  build               Build and install llama-server from source (ROCm)
34	  remove              Remove a previous llama-server installation
35	  version             Print version and exit
36	
37	Environment:
38	  WIRE_CONFIG         Config file path (default: ~/.config/wire/config.yaml)
39	  WIRE_LLAMA_SRC      llama.cpp source directory (default: ~/Development/llama.cpp)
40	  WIRE_GPU_TARGET     AMD GPU target (default: gfx1151; find yours: rocminfo | grep gfx)
41	  WIRE_PREFIX         Install prefix (default: ~/.local)
42	`
43	
44	// Run dispatches CLI commands from the given argument slice (os.Args[1:]).
45	// It returns an exit code suitable for os.Exit.
46	func Run(args []string) int {
47		if err := dispatch(args); err != nil {
48			fmt.Fprintln(os.Stderr, "wire:", err)
49			return 1
50		}
51		return 0
52	}
53	
54	func dispatch(args []string) error {
55		if len(args) == 0 {
56			fmt.Print(usageText)
57			return nil
58		}
59		switch args[0] {
60		case "help", "--help", "-h":
61			fmt.Print(usageText)
62			return nil
63		case "start":
64			return runStart()
65		case "stop":
66			return runStop()
67		case "status":
68			return runStatus()
69		case "swap":
70			if len(args) < 3 {
71				return fmt.Errorf("swap requires <backend> and <model>\nUsage: wire swap <backend> <model>")
72			}
73			return runSwap(args[1], args[2])
74		case "version", "--version", "-v":
75			fmt.Printf("wire %s (%s) built %s\n", internal.Version, internal.Commit, internal.BuildDate)
76			return nil
77		case "build":
78			return runBuild(args[1:])
79		case "remove":
80			return runRemove(args[1:])
81		default:
82			fmt.Print(usageText)
83			return fmt.Errorf("unknown command: %q", args[0])
84		}
85	}
86	
87	// listenURL converts the listen address from config to an http:// URL.
88	func listenURL(listen string) string {
89		if strings.HasPrefix(listen, ":") {
90			return "http://localhost" + listen
91		}
92		return "http://" + listen
93	}
94	
95	func runStart() error {
96		cfg, err := config.Load()
97		if err != nil {
98			return fmt.Errorf("loading config: %w", err)
99		}
100	
101		pidPath := pidfile.Path()
102		if err := pidfile.Write(pidPath); err != nil {
103			return err
104		}
105		defer os.Remove(pidPath)
106	
107		// bgCtx drives the process manager; cancelled only after gateway drains.
108		bgCtx, bgCancel := context.WithCancel(context.Background())
109		defer bgCancel()
110	
111		// shutCtx is cancelled by SIGTERM/SIGINT. Its Cause is the received signal.
112		shutCtx, stop := signal.NotifyContext(bgCtx, syscall.SIGTERM, syscall.SIGINT)
113		defer stop()
114	
115		// sighupCh receives SIGHUP for config reload.
116		sighupCh := make(chan os.Signal, 1)
117		signal.Notify(sighupCh, syscall.SIGHUP)
118		defer signal.Stop(sighupCh)
119	
120		mgr := process.New(cfg, slog.Default())
121		if err := mgr.Start(bgCtx); err != nil {
122			return fmt.Errorf("starting process manager: %w", err)
123		}
124	
125		gw := gateway.New(cfg, mgr, slog.Default())
126		gwErrCh := make(chan error, 1)
127		go func() { gwErrCh <- gw.ListenAndServe(shutCtx) }()
128	
129		slog.Info("wire ready", "listen", cfg.Listen, "version", internal.Version, "commit", internal.Commit)
130	
131		// swapMu serialises SIGHUP handling so overlapping reloads are dropped.
132		var swapMu sync.Mutex
133	
134		for {
135			select {
136			case err := <-gwErrCh:
137				bgCancel()
138				_ = mgr.Stop()
139				if err != nil {
140					return fmt.Errorf("gateway error: %w", err)
141				}
142				return nil
143	
144			case <-shutCtx.Done():
145				if cause := context.Cause(shutCtx); cause != nil {
146					slog.Info("shutting down", "cause", cause)
147				}
148				stop() // release signal resources early
149				// Wait for gateway to drain connections, then stop process manager.
150				if err := <-gwErrCh; err != nil {
151					slog.Error("gateway shutdown error", "error", err)
152				}
153				bgCancel()
154				return mgr.Stop()
155	
156			case <-sighupCh:
157				if !swapMu.TryLock() {
158					slog.Warn("SIGHUP received while swap in progress, ignoring")
159					continue
160				}
161				go func() {
162					defer swapMu.Unlock()
163					newCfg, loadErr := config.Load()
164					if loadErr != nil {
165						slog.Error("failed to reload config on SIGHUP", "error", loadErr)
166						return
167					}
168					for name, b := range newCfg.Backends {
169						oldB, ok := cfg.Backends[name]
170						if !ok || !b.IsManaged() {
171							continue
172						}
173						if b.Model != oldB.Model {
174							slog.Info("swapping backend model", "backend", name, "old", oldB.Model, "new", b.Model)
175							if swapErr := mgr.Swap(bgCtx, name, b.Model); swapErr != nil {
176								slog.Error("model swap failed", "backend", name, "error", swapErr)
177							}
178						}
179					}
180					cfg = newCfg
181				}()
182			}
183		}
184	}
185	
186	func runStop() error {
187		pidPath := pidfile.Path()
188		pid, err := pidfile.Read(pidPath)
189		if err != nil {
190			return err
191		}
192		proc, err := os.FindProcess(pid)
193		if err != nil {
194			return fmt.Errorf("finding process %d: %w", pid, err)
195		}
196		if err := proc.Signal(syscall.SIGTERM); err != nil {
197			return fmt.Errorf("sending SIGTERM to pid %d: %w", pid, err)
198		}
199	
200		// Poll /proc/<pid> via kill -0 for up to 10 seconds.
201		deadline := time.Now().Add(10 * time.Second)
202		for time.Now().Before(deadline) {
203			if err := proc.Signal(syscall.Signal(0)); err != nil {
204				fmt.Printf("wire stopped (pid %d)\n", pid)
205				return nil
206			}
207			time.Sleep(200 * time.Millisecond)
208		}
209	
210		// Still alive: force kill.
211		_ = proc.Signal(syscall.SIGKILL)
212		fmt.Printf("wire force-killed (pid %d)\n", pid)
213		return nil
214	}
215	
216	func runStatus() error {
217		cfg, err := config.Load()
218		if err != nil {
219			return fmt.Errorf("loading config: %w", err)
220		}
221	
222		baseURL := listenURL(cfg.Listen)
223		client := &http.Client{Timeout: 5 * time.Second}
224	
225		healthResp, err := client.Get(baseURL + "/health")
226		if err != nil {
227			fmt.Println("wire is not running")
228			os.Exit(1)
229		}
230		defer healthResp.Body.Close()
231	
232		var healthBody struct {
233			Status string `json:"status"`
234		}
235		_ = json.NewDecoder(healthResp.Body).Decode(&healthBody)
236		overall := healthBody.Status
237		if overall == "" {
238			if healthResp.StatusCode == http.StatusOK {
239				overall = "healthy"
240			} else {
241				overall = "degraded"
242			}
243		}
244		fmt.Printf("wire: %s (%s)\n", overall, baseURL)
245	
246		modelsResp, err := client.Get(baseURL + "/v1/models")
247		if err != nil {
248			return nil
249		}
250		defer modelsResp.Body.Close()
251	
252		var modelsBody struct {
253			Data []struct {
254				ID string `json:"id"`
255			} `json:"data"`
256		}
257		if err := json.NewDecoder(modelsResp.Body).Decode(&modelsBody); err != nil {
258			return nil
259		}
260	
261		for _, m := range modelsBody.Data {
262			b, ok := cfg.Backends[m.ID]
263			model := m.ID
264			if ok {
265				if b.IsManaged() {
266					model = b.Model
267				} else {
268					model = b.URL
269				}
270			}
271			fmt.Printf("  %-14s %-40s %s\n", m.ID+":", model, overall)
272		}
273		return nil
274	}
275	
276	func runSwap(backend, model string) error {
277		cfg, err := config.Load()
278		if err != nil {
279			return fmt.Errorf("loading config: %w", err)
280		}
281	
282		b, ok := cfg.Backends[backend]
283		if !ok {
284			return fmt.Errorf("backend %q not found in config", backend)
285		}
286		if b.IsExternal() {
287			return fmt.Errorf("backend %q is external and cannot be swapped", backend)
288		}
289	
290		b.Model = model
291		cfg.Backends[backend] = b
292		if err := config.WriteFile(cfg); err != nil {
293			return err
294		}
295	
296		pidPath := pidfile.Path()
297		pid, err := pidfile.Read(pidPath)
298		if err != nil {
299			return err
300		}
301		proc, err := os.FindProcess(pid)
302		if err != nil {
303			return fmt.Errorf("finding process: %w", err)
304		}
305		if err := proc.Signal(syscall.SIGHUP); err != nil {
306			return fmt.Errorf("sending SIGHUP to pid %d: %w", pid, err)
307		}
308	
309		fmt.Printf("sent reload signal to wire (pid %d); run 'wire status' to check progress\n", pid)
310		return nil
311	}
