321		fs.StringVar(&opts.GPUTarget, "gpu-target", opts.GPUTarget, "AMD GPU target (find yours: rocminfo | grep gfx)")
322		fs.StringVar(&opts.Prefix, "prefix", opts.Prefix, "install prefix")
323		if err := fs.Parse(args); err != nil {
324			return err
325		}
326	
327		return build.Build(opts)
328	}
