330	func runRemove(args []string) error {
331		opts, err := build.DefaultOptions()
332		if err != nil {
333			return err
334		}
335	
336		fs := flag.NewFlagSet("remove", flag.ContinueOnError)
337		fs.StringVar(&opts.Source, "source", opts.Source, "path to llama.cpp git checkout")
338		if err := fs.Parse(args); err != nil {
339			return err
340		}
341	
342		return build.Remove(opts)
