106	
107		// bgCtx drives the process manager; cancelled only after gateway drains.
108		bgCtx, bgCancel := context.WithCancel(context.Background())
109		defer bgCancel()
110	
111		// shutCtx is cancelled by SIGTERM/SIGINT. Its Cause is the received signal.
112		shutCtx, stop := signal.NotifyContext(bgCtx, syscall.SIGTERM, syscall.SIGINT)
113		defer stop()
114	
115		// sighupCh receives SIGHUP for config reload.
116		sighupCh := make(chan os.Signal, 1)
117		signal.Notify(sighupCh, syscall.SIGHUP)
118		defer signal.Stop(sighupCh)
119	
120		mgr := process.New(cfg, slog.Default())
121		if err := mgr.Start(bgCtx); err != nil {
