130	
131		// swapMu serialises SIGHUP handling so overlapping reloads are dropped.
132		var swapMu sync.Mutex
133	
134		for {
135			select {
136			case err := <-gwErrCh:
137				bgCancel()
138				_ = mgr.Stop()
139				if err != nil {
140					return fmt.Errorf("gateway error: %w", err)
141				}
142				return nil
143	
144			case <-shutCtx.Done():
145				if cause := context.Cause(shutCtx); cause != nil {
146					slog.Info("shutting down", "cause", cause)
147				}
148				stop() // release signal resources early
149				// Wait for gateway to drain connections, then stop process manager.
150				if err := <-gwErrCh; err != nil {
151					slog.Error("gateway shutdown error", "error", err)
152				}
153				bgCancel()
154				return mgr.Stop()
155	
156			case <-sighupCh:
157				if !swapMu.TryLock() {
158					slog.Warn("SIGHUP received while swap in progress, ignoring")
159					continue
160				}
161				go func() {
162					defer swapMu.Unlock()
163					newCfg, loadErr := config.Load()
164					if loadErr != nil {
165						slog.Error("failed to reload config on SIGHUP", "error", loadErr)
166						return
167					}
168					for name, b := range newCfg.Backends {
169						oldB, ok := cfg.Backends[name]
170						if !ok || !b.IsManaged() {
171							continue
172						}
173						if b.Model != oldB.Model {
174							slog.Info("swapping backend model", "backend", name, "old", oldB.Model, "new", b.Model)
175							if swapErr := mgr.Swap(bgCtx, name, b.Model); swapErr != nil {
176								slog.Error("model swap failed", "backend", name, "error", swapErr)
177							}
178						}
179					}
180					cfg = newCfg
181				}()
182			}
183		}
184	}
