228			os.Exit(1)
229		}
230		defer healthResp.Body.Close()
231	
232		var healthBody struct {
233			Status string `json:"status"`
234		}
235		_ = json.NewDecoder(healthResp.Body).Decode(&healthBody)
236		overall := healthBody.Status
237		if overall == "" {
238			if healthResp.StatusCode == http.StatusOK {
239				overall = "healthy"
240			} else {
241				overall = "degraded"
242			}
243		}
244		fmt.Printf("wire: %s (%s)\n", overall, baseURL)
245	
246		modelsResp, err := client.Get(baseURL + "/v1/models")
247		if err != nil {
248			return nil
249		}
250		defer modelsResp.Body.Close()
251	
252		var modelsBody struct {
253			Data []struct {
254				ID string `json:"id"`
255			} `json:"data"`
256		}
257		if err := json.NewDecoder(modelsResp.Body).Decode(&modelsBody); err != nil {
