13	// newTestHub creates a Hub wired to a fake snapshotFn and the provided event
14	// channel. No GPU discovery runs (discoverGPUs returns empty on most hosts).
15	func newTestHub(t *testing.T, events chan ServerEvent, backends []BackendStatus) *Hub {
16		t.Helper()
17		h := NewHub(slog.Default(), events, func() []BackendStatus { return backends })
18		h.gpus = nil // disable GPU polling in unit tests
19		return h
20	}
