22	func TestHub_Subscribe_getsSnapshot(t *testing.T) {
23		events := make(chan ServerEvent, 8)
24		h := newTestHub(t, events, nil)
25		h.Start()
26		defer h.Stop()
27	
28		ch, unsub := h.Subscribe()
29		defer unsub()
30	
31		select {
32		case msg := <-ch:
33			if msg.Kind != MsgSnapshot {
34				t.Errorf("first message kind: got %v, want MsgSnapshot", msg.Kind)
35			}
36			if msg.Snap == nil {
37				t.Error("Snap must not be nil")
38			}
39		case <-time.After(time.Second):
40			t.Fatal("timeout waiting for snapshot")
41		}
42	}
