51		defer unsub()
52	
53		// Drain the snapshot.
54		<-ch
55	
56		ev := ServerEvent{Kind: EventRaw, Backend: "local", Message: "hello"}
57		events <- ev
58	
59		select {
60		case msg := <-ch:
61			if msg.Kind != MsgServerEvent {
