75		h.Start()
76		defer h.Stop()
77	
78		ch1, unsub1 := h.Subscribe()
79		ch2, unsub2 := h.Subscribe()
80		defer unsub1()
81		defer unsub2()
82	
83		<-ch1
84		<-ch2
85	
86		events <- ServerEvent{Kind: EventRaw, Message: "broadcast"}
87	
88		for _, ch := range []<-chan HubMessage{ch1, ch2} {
89			select {
