101		events := make(chan ServerEvent, 8)
102		h := newTestHub(t, events, nil)
103		h.Start()
104		defer h.Stop()
105	
106		ch, unsub := h.Subscribe()
107		<-ch // drain snapshot
108	
109		unsub()
110	
111		// Events sent after unsubscribe must not appear on ch.
112		events <- ServerEvent{Kind: EventRaw, Message: "after-unsub"}
113	
114		select {
115		case msg := <-ch:
116			t.Errorf("received unexpected message after unsubscribe: %+v", msg)
117		case <-time.After(100 * time.Millisecond):
118			// expected
119		}
120	}
121	
122	func TestHub_Stop_closesChannels(t *testing.T) {
123		events := make(chan ServerEvent, 8)
124		h := newTestHub(t, events, nil)
125		h.Start()
126	
127		ch, _ := h.Subscribe()
128		<-ch // drain snapshot
129	
